const realPlay=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(){if(this.loop && window.rejectAmbience)return Promise.reject(new DOMException('Playback requires a user gesture','NotAllowedError'));return realPlay.call(this);};
const createMediaSource=AudioContext.prototype.createMediaElementSource;AudioContext.prototype.createMediaElementSource=function(audio){const source=createMediaSource.call(this,audio),connect=source.connect;source.connect=function(target,...args){audio.fixtureGain=target;if(!audio.loop)window.gains.push(target);return connect.call(this,target,...args);};return source;};
