store.set('chat:fixture',{connection:'a',enableMixer:true,styleParam:'instructions',prefetch:1,concurrency:1,chunk:500,normalizeLoudness:true,fixed:[{speaker:'Narrator',voice:'n',style:'Measured narration'},{speaker:'You',voice:'y',style:''},{speaker:'Mira',voice:'m',style:'Warm',route:'native:b'}],casts:{'native:a':[]}});
const message={id:'reply',index_in_chat:0,name:'Mira',content:'The hall fell silent. "Welcome." A new story begins.'};
function wav(amplitude,frequency=220){const count=24000,buffer=new ArrayBuffer(44+count*2),view=new DataView(buffer);function text(offset,value){for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i));}text(0,'RIFF');view.setUint32(4,36+count*2,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,24000,true);view.setUint32(28,48000,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,count*2,true);for(let i=0;i<count;i++)view.setInt16(44+i*2,Math.sin(i*2*Math.PI*frequency/24000)*32767*amplitude,true);return buffer;}
const realFetch=window.fetch;window.fetch=async(url,options={})=>{
 if(url==='/fixture-ambience.wav'){window.bedDownloads=(window.bedDownloads||0)+1;return new Response(wav(0.06,window.mixTones?660:220),{headers:{'Content-Type':'audio/wav'}});}
 if(url==='/fixture-sfx.wav'){window.foleyDownloads++;return new Response(wav(0.06,window.mixTones?880:220),{headers:{'Content-Type':'audio/wav'}});}
 if(!String(url).startsWith('/api/v1'))return realFetch(url,options);
 if(url.endsWith('/spindle')){window.branchRequest=window.fixtureBranch || 'staging';return Response.json({extensions:[{identifier:'choir',metadata:{branch:window.branchRequest}}]});}
 if(url.endsWith('/tts/synthesize')){const input=JSON.parse(options.body);window.calls.push(input);if(window.ttsError)return Response.json({error:window.ttsError},{status:502});if(window.holdSpeechText && input.text.includes(window.holdSpeechText))await new Promise((resolve,reject)=>{const cancel=()=>reject(new DOMException('Stopped','AbortError'));options.signal.addEventListener('abort',cancel,{once:true});window.releaseSpeech=()=>{options.signal.removeEventListener('abort',cancel);resolve();};});return new Response(wav(input.voice==='m'?0.4:0.06),{headers:{'Content-Type':'audio/wav'}});}
 if(url.includes('/providers'))return Response.json({providers:[{id:'openai_tts',capabilities:{parameters:{instructions:{type:'string'}}}}]});
 if(url.endsWith('/voices'))return Response.json({voices:['n','y','m'].map(id=>({id,name:id}))});
 if(url.includes('/connections?'))return Response.json({data:[{id:'planner',name:'Planner',provider:'test',model:'text-model'}]});
 return Response.json({data:[{id:'a',name:'Narration',provider:'openai_tts',model:'model-a'},{id:'b',name:'Characters',provider:'openai_tts',model:'model-b'},{id:'c',name:'Fish Audio',provider:'fish_audio',model:'s2.1-pro'}]});
};
